css:
:root {
  --color-bg: #000000;
  --color-surface: #0a0a0a;
  --color-text: #ffffff;
  --color-text-muted: #ffffff;
  --color-border: #ffffff;
  --color-accent: #ffff00;
  --color-danger: #ff6b6b;
  --color-danger-bg: #2a0000;
  color-scheme: dark;
}

/* Beyond colors: a highly visible focus ring and thicker structural
   borders, the two things a high-contrast/low-vision theme needs most
   and colors alone can't provide. */
*:focus-visible {
  outline: 3px solid #ffff00;
  outline-offset: 2px;
}

input,
select,
textarea,
button,
table,
th,
td {
  border-width: 2px !important;
}
